window.kbPageData["views/entry/k-4982f03b1299726b"] = {"key":"entry/k-4982f03b1299726b","state":{"route":"entry/k-4982f03b1299726b"},"node":{"id":"k-4982f03b1299726b","mode":"k","title":"票据付款义务与取得对价","type":"制度与规则","domain":"经济","reading":"","intro":"","priority":100,"aliases":["有价证券债务人的支付属于单方义务"],"qs":["国考 2023 地市级 行测#7"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"票据债务人依法按票据记载承担付款义务。取得票据原则上应给付对价，依法因税收、继承、赠与无偿取得的情形除外。","review":{"definition":"票据债务人依法按票据记载承担付款义务。取得票据原则上应给付对价，依法因税收、继承、赠与无偿取得的情形除外。","explanation":"本题为选非题，A项把请求相应对价概括为有价证券债务人的一般权利，所给答案选A。以票据为例，债务人不能仅凭自己负有票据付款义务就向持票人请求对价。对与自己有直接债权债务关系且未履行约定义务的持票人，债务人可依法抗辩。解析中的“单方义务”应限于证券上的付款关系理解，对价还可能来自取得证券的基础交易。","references":[{"source":"web-0f691ce75929a2f1","location":"第十条至第十三条","quote":"票据的取得，必须给付对价"}],"evidence":"有价证券的债务人可以请求债权人支付相应对价","disposition":"独立词条","basis":"据原题与所列资料编释。"}},"questions":{"国考 2023 地市级 行测#7":{"paper":"国考 2023 地市级 行测","n":7,"mod":"常识判断","src":["64bc3a15d27a04e94940.pdf",2],"asrc":["f3ab652d8e31c5bbdabc.pdf",3],"card":"5e41672151f25e24d1409801","links":[{"id":"k-4982f03b1299726b","role":"直接考查","why":"债务人的单方支付义务决定其无权向证券权利人请求对应给付。"}]}},"terms":{},"references":{"web-0f691ce75929a2f1":{"name":"《中华人民共和国票据法》（商务部转载）","url":"https://www.mofcom.gov.cn/zcfb/zgdwjjmywg/art/2004/art_68539dd87ed147048841034d1c5d208f.html"}},"topics":[],"units":{"k-4982f03b1299726b":[["国考 2023 地市级 行测#7"]]}};
